//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error represents a condition that may recover.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;
    let mut delay = config.base_delay_ms;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= max_attempts => {
                return Err(error)
            }
            Err(_) => {
                sleeper.sleep_ms(delay.min(config.max_delay_ms));
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("temporary failure".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_sleeping_or_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid job".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_limit_includes_the_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(3, 7, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still unavailable".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![7, 14]);
    }

    #[test]
    fn zero_attempt_budget_still_makes_one_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(0, 1, 10), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("failure".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("failure".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn delay_growth_handles_integer_overflow() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4, u64::MAX, u64::MAX), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("failure".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("failure".into())));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![u64::MAX; 3]);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_until_success() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 12,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        match attempts {
            1 | 2 => Err(RetryError::Transient("service unavailable".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![5, 10]);
}

#[test]
fn public_api_stops_at_max_attempts() {
    let config = RetryConfig {
        max_attempts: 2,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
    assert_eq!(attempts, 2);
    assert_eq!(sleeper.sleeps, vec![10]);
}
